import numpy as np
import matplotlib.pyplot as plt

def _boxsum(mask, r):
    k = 2 * r + 1
    ap = np.pad(mask.astype(np.float64), r, mode='constant')
    cs = np.cumsum(np.cumsum(ap, 0), 1)
    cs = np.pad(cs, ((1, 0), (1, 0)))
    H, W = mask.shape
    return cs[k:k+H, k:k+W] - cs[0:H, k:k+W] - cs[k:k+H, 0:W] + cs[0:H, 0:W]

def _erode(mask, r):
    if r <= 0:
        return mask
    return _boxsum(mask, r) >= (2 * r + 1) ** 2 - 0.5

def _dilate(mask, r):
    if r <= 0:
        return mask
    return _boxsum(mask, r) > 0.5

def _opening(m, r):
    return _dilate(_erode(m, r), r)

def _closing(m, r):
    return _erode(_dilate(m, r), r)

# Syntetyczna maska CFAR: 4 zwarte cele (statki) + rozsiany speckle (falszywe alarmy).
_rng = np.random.default_rng(11)
_H = _W = 140
RAW = np.zeros((_H, _W), bool)
SHIPS = [(30, 40, 3), (95, 55, 4), (55, 105, 3), (110, 110, 3)]
for _r0, _c0, _s in SHIPS:
    RAW[_r0:_r0+_s, _c0:_c0+_s] = True
RAW |= (_rng.random((_H, _W)) < 0.015)
